begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(8);
insert into public.organizations(id,name) values ('18000000-0000-0000-0000-000000000001','Synthetic');
insert into public.clients(id,organization_id,name) values ('18000000-0000-0000-0000-000000000002','18000000-0000-0000-0000-000000000001','Synthetic');
insert into public.staffs(id,organization_id,name) values ('18000000-0000-0000-0000-000000000003','18000000-0000-0000-0000-000000000001','Synthetic');
insert into public.shifts(id,organization_id,client_id,start_at,end_at) values ('18000000-0000-0000-0000-000000000004','18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000002','2026-11-01 00:00+00','2026-11-01 01:00+00');
create temporary table snapshots(value bytea);
insert into snapshots select private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000004');
select is(private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000099','18000000-0000-0000-0000-000000000004'),null::bytea,'other organization has no snapshot');
select ok(not has_function_privilege('mcp_import','private.mcp_shift_change_snapshot(uuid,uuid)','execute') and not has_function_privilege('authenticated','private.mcp_shift_change_snapshot(uuid,uuid)','execute'),'application roles cannot execute snapshot');
set local timezone = 'Asia/Tokyo';
select is(private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000004'),(select value from snapshots),'snapshot is independent of session timezone');
update public.shifts set google_sync_status='failed',google_sync_error='synthetic' where id='18000000-0000-0000-0000-000000000004';
select is(private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000004'),(select value from snapshots),'sync status alone does not invalidate proposal');
update public.shifts set start_at=start_at + interval '1 minute' where id='18000000-0000-0000-0000-000000000004';
select isnt(private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000004'),(select value from snapshots),'parent change invalidates snapshot');
update snapshots set value=private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000004');
insert into public.shift_staffs(shift_id,staff_id) values ('18000000-0000-0000-0000-000000000004','18000000-0000-0000-0000-000000000003');
select isnt(private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000004'),(select value from snapshots),'staff change invalidates snapshot');
insert into public.shift_segments(id,shift_id,start_at,end_at) values ('18000000-0000-0000-0000-000000000005','18000000-0000-0000-0000-000000000004','2026-11-01 00:00+00','2026-11-01 01:00+00');
update snapshots set value=private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000004');
update public.shift_segments set end_at=end_at - interval '1 minute' where id='18000000-0000-0000-0000-000000000005';
select isnt(private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000004'),(select value from snapshots),'segment change invalidates snapshot');
update snapshots set value=private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000004');
insert into public.shift_segment_staffs(segment_id,staff_id) values ('18000000-0000-0000-0000-000000000005','18000000-0000-0000-0000-000000000003');
select isnt(private.mcp_shift_change_snapshot('18000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000004'),(select value from snapshots),'segment staff change invalidates snapshot');
select * from finish();
rollback;
